//#region src/skill/frontmatter.ts
const parseFrontmatter = (raw) => {
	const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
	if (!match) return {
		data: {},
		content: raw
	};
	const parsed = (0, yaml.parse)(match[1] ?? "");
	return {
		data: require_to_error_message.isPlainObject(parsed) ? parsed : {},
		content: match[2] ?? ""
	};
};
